  let tgt=0;const sea=[.28,.04,.55,1];
  if(GS.au===0)tgt=0;else if(S.aur==='on')tgt=1;else if(S.aur==='auto'){let sf=0;for(let i=0;i<4;i++)sf+=SW[i]*sea[i];tgt=sf*Math.pow(env.nf,2.2)*(1-env.ov*1.1)*(.75+.25*Math.sin(h*2.7));const dy=GS.day|0,rh=Math.abs(Math.sin(dy*12.9898+4.1)*43758.5453)%1,st=20+rh*3,wn=Math.sin(Math.PI*cl(((h<12?h+24:h)-st)/(1.6+rh*2.4),0,1));if(rh>.5&&wn>0)tgt=Math.max(tgt,wn*(.55+.4*rh)*Math.pow(env.nf,1.5)*(1-env.ov*1.1))}
