  tops[1]=[top[0]*.93,top[1]*.99,Math.min(255,top[2]*1.04)];hors[1]=hor;
  tops[2]=mix3(top,[118,150,196],.2*day);hors[2]=mix3(hor,[255,196,118],.3*day+.08*env.golden);
