  if(env.sunVis&&env.sunEl>.04){a=S.ray*(.2+.8*env.golden)*.2*(1-env.ov*.92)*(1-env.rain);col='255,224,150';sx=env.sun.x*SC4;sy=env.sun.y*SC4}
  else if(env.moonVis&&env.nf>.5&&env.moonEl>.05){a=S.ray*.07*(1-env.ov)*cl((env.nf-.5)*2,0,1);col='170,196,255';sx=env.moon.x*SC4;sy=env.moon.y*SC4}
